insert into public.organ_content (system, slug, about, location, function, fun_fact) values
('skeletal','backbone','Your backbone, or spine, is a stack of small bones called vertebrae.','Down the middle of your back, from your neck to your bottom.','It holds your body up, lets you bend and twist, and protects the spinal cord inside it.','A giraffe has the same number of neck bones as you: seven!'),
('skeletal','carpals','The carpals are eight small, pebble-shaped wrist bones in two rows.','In your wrist, between the forearm and the palm.','They let your wrist bend and twist smoothly.','The tiny pisiform carpal is about the size of a pea.'),
('skeletal','cervical-vertebrae','The cervical vertebrae are the seven small bones of your neck.','In your neck, at the top of the spine.','They hold up your head and let you nod and turn it.','The top two neck bones are called the atlas and the axis; the atlas holds up your skull like the giant Atlas held up the sky.'),
('skeletal','clavicle','The clavicle, or collarbone, is a long S-shaped bone.','At the front of each shoulder, below the neck.','It acts like a strut that holds the shoulder away from the body so the arm can move freely.','The clavicle is the first bone to start hardening in a baby before birth.'),
('skeletal','collarbone','The collarbone is a long, thin bone shaped a bit like the letter S.','At the front of each shoulder, below your neck.','It connects your arm to your body and keeps your shoulder in place.','The collarbone is one of the most commonly broken bones, often from falling on an outstretched hand.'),
('skeletal','costal-cartilages','Costal cartilages are bars of bendy cartilage.','At the front of the chest, joining the ribs to the breastbone.','They let the ribcage stretch and spring back when you breathe.','They''re why your chest can expand — solid bone there would make breathing much harder.'),
('skeletal','ethmoid-bone','The ethmoid is a light, spongy bone full of small air cells.','Between the eyes, behind the nose.','It separates the nose from the brain and forms part of the nasal cavity and eye sockets.','Tiny holes in it let smell nerves pass from the nose up to the brain.'),
('skeletal','femur','The femur, or thigh bone, is the longest and strongest bone in the body.','In the thigh, between the hip and the knee.','It carries body weight and transfers the pull of powerful leg muscles.','A femur can support up to 30 times the weight of your body.'),
('skeletal','fibula','The fibula is the thin outer bone of the lower leg.','On the outer side of the lower leg.','It steadies the ankle and gives leg muscles a place to attach; it carries little weight.','Surgeons sometimes take a piece of fibula to rebuild a jaw, because you can manage without part of it.'),
('skeletal','finger-bones','Finger bones are called phalanges; each finger has three and the thumb has two.','In your fingers and thumb.','They let your fingers bend to grip, pinch and type.','Fingers have no muscles inside them — tendons from forearm muscles pull them like strings.'),
('skeletal','foot-bones','Each foot has 26 bones: ankle bones, foot bones and toe bones.','In your ankle, foot and toes.','They carry your weight, form the arch of your foot and help you balance and walk.','Your feet together have over 50 bones.'),
('skeletal','forearm-bones','Your forearm has two bones side by side: the radius and the ulna.','Between your elbow and your wrist.','Together they let you turn your hand palm-up and palm-down.','When you turn a doorknob, your radius rolls around your ulna.'),
('skeletal','frontal-bone','The frontal bone is the large curved bone of the forehead.','At the front of the skull, above the eyes.','It protects the front of the brain and forms the top of the eye sockets.','It contains air spaces called the frontal sinuses, which make the skull lighter.'),
('skeletal','hand-bones','Each hand has 27 small bones: wrist bones, palm bones and finger bones.','In your wrist, palm and fingers.','They let you grip, write, draw and make tiny, careful movements.','Your two hands together hold about a quarter of all the bones in your body.'),
('skeletal','hip-bones','The hip bones are two large, curved bones that make a bowl shape with the bottom of the spine.','Around your lower tummy and bottom.','They hold up your upper body, protect organs like the bladder and connect your legs to your body.','Doctors can often tell if a skeleton was a man or a woman by the shape of the hip bones.'),
('skeletal','humerus','The humerus is the long bone of the upper arm.','Between the shoulder and the elbow.','Its round top fits into the shoulder socket and its bottom forms part of the elbow hinge.','The ulnar nerve passes near the elbow end of the humerus — that''s your ''funny bone''.'),
('skeletal','hyoid','The hyoid is a small U-shaped bone.','In the front of your neck, just above the voice box.','It supports your tongue and helps you swallow and speak.','The hyoid is the only bone that doesn''t touch any other bone.'),
('skeletal','jaw','The lower jaw, or mandible, is the only bone in your skull that can move.','At the bottom of your face, holding your lower teeth.','It opens and closes your mouth so you can chew, talk and yawn.','The mandible is the largest and strongest bone in your face.'),
('skeletal','kneecap','The kneecap, or patella, is a small round bone.','At the front of your knee.','It protects the knee joint and helps your thigh muscles straighten your leg.','Babies are born with kneecaps made of soft cartilage; they turn into bone by age 3–5.'),
('skeletal','lower-leg-bones','Your lower leg has two bones: the thick tibia (shin bone) and the thin fibula.','Between your knee and your ankle.','The tibia carries your weight; the fibula helps hold the ankle steady and gives muscles a place to attach.','You can feel your tibia right under the skin at the front of your shin.'),
('skeletal','lumbar-vertebrae','The lumbar vertebrae are the five biggest, strongest bones of the spine.','In your lower back.','They carry most of your upper body''s weight and let you bend forward and back.','Lower back pain is so common because these bones carry so much weight.'),
('skeletal','maxilla','The maxilla is the upper jaw bone, made of two halves joined in the middle.','In the middle of the face, holding the upper teeth.','It holds the upper teeth and forms the roof of the mouth and the floor of the eye sockets.','Unlike the lower jaw, the upper jaw can''t move on its own.'),
('skeletal','metacarpals','The metacarpals are the five long bones of the palm.','Inside your palm, one leading to each finger.','They form the frame of your hand and the knuckles when you make a fist.','The thumb''s metacarpal is the shortest and moves the most.'),
('skeletal','metatarsals','The metatarsals are the five long bones in the middle of the foot.','Between the ankle bones and the toes.','They form the arches of the foot and push you off the ground when you walk.','Runners sometimes get tiny ''stress fractures'' in their metatarsals from lots of pounding.'),
('skeletal','nasal-bones','The two nasal bones are small, thin bones.','At the top of the nose, between the eyes.','They form the bridge of the nose; the rest of the nose is cartilage.','The bendy tip of your nose has no bone at all.'),
('skeletal','occipital-bone','The occipital bone forms the back and base of the skull.','At the back of your head.','It protects the back of the brain and has a big hole where the spinal cord passes through.','That hole is called the foramen magnum, which means ''great hole'' in Latin.'),
('skeletal','other-facial-bones','This group includes the lacrimal bones, palatine bones, vomer and nasal conchae.','Inside the face: around the eye sockets, nose and roof of the mouth.','They form the inside walls of the nose, part of the eye sockets and the back of the hard palate.','The lacrimal bones are the smallest bones of the face — about the size of a fingernail.'),
('skeletal','parietal-bones','The two parietal bones form the top and sides of the skull.','On top of your head, left and right.','They protect the upper part of the brain.','They meet in a wiggly joint called a suture that locks them together like puzzle pieces.'),
('skeletal','patella','The patella, or kneecap, is a small triangular bone inside a tendon.','At the front of the knee.','It protects the knee and works like a pulley so the thigh muscles can straighten the leg more strongly.','The patella is the largest sesamoid bone — a bone that grows inside a tendon.'),
('skeletal','pelvis','The pelvis is the ring of bone made by the two hip bones and the sacrum.','Around the lower abdomen and bottom.','It carries the weight of the upper body to the legs and protects the bladder and other organs.','Each hip bone is made of three bones (ilium, ischium, pubis) that fuse during the teenage years.'),
('skeletal','radius','The radius is one of the two forearm bones.','On the thumb side of the forearm.','It rotates around the ulna so you can turn your palm up and down.','A broken wrist is most often a break at the end of the radius.'),
('skeletal','ribcage','The ribcage is a cage of curved rib bones joined to a flat breastbone at the front.','Around your chest.','It protects your heart and lungs and moves when you breathe in and out.','Most people have 12 pairs of ribs — 24 ribs in total.'),
('skeletal','ribs','Ribs are long, curved bones; most are joined to the breastbone by bendy cartilage.','Around your chest, from your spine to the front.','They protect the heart and lungs and lift up and out when you breathe in.','The lowest two pairs are called ''floating ribs'' because they don''t reach the breastbone.'),
('skeletal','sacrum-coccyx','The sacrum is a triangle-shaped bone, and the coccyx is the small tailbone below it.','At the very bottom of your spine, between your hip bones.','The sacrum joins the spine to the hips; the tailbone gives some muscles a place to attach.','The sacrum starts as five separate bones that fuse together as you grow up.'),
('skeletal','scapula','The scapula, or shoulder blade, is a flat triangular bone.','On the upper back, behind each shoulder.','It forms the shoulder socket and anchors 17 different muscles.','The scapula can slide and rotate on your back, which gives your arm its huge range of movement.'),
('skeletal','shoulder-blade','The shoulder blade is a flat, triangle-shaped bone.','On the upper back, one behind each shoulder.','Many arm and back muscles attach to it, so you can lift, throw and swing your arms.','Its scientific name, scapula, comes from a Latin word for shovel.'),
('skeletal','skull','The skull is the hard, bony helmet of your head. It is made of many bones joined together.','At the very top of your body, around your brain and face.','It protects your brain, holds your eyes safe and gives your face its shape.','A baby''s skull has soft spots so it can squeeze and grow; they close up by about age 2.'),
('skeletal','sphenoid-bone','The sphenoid is a bat-shaped bone in the middle of the skull base.','Deep in the skull, behind the eyes.','It links many skull bones together and forms part of each eye socket.','It touches every other bone of the cranium, which is why it''s called the ''keystone'' of the skull.'),
('skeletal','sternum','The sternum, or breastbone, is a flat bone shaped a little like a tie.','In the middle of your chest.','It holds the ribs together at the front and protects the heart.','The sternum has three parts: the manubrium, the body and the small xiphoid process.'),
('skeletal','tarsals','The tarsals are seven ankle bones, including the heel bone (calcaneus) and the talus.','In your ankle and the back half of your foot.','They carry your weight from the leg into the foot and let the ankle move.','The calcaneus is the largest bone in the foot and takes the hit every time your heel lands.'),
('skeletal','teeth','Teeth are hard, white structures covered in enamel.','In your upper jaw and lower jaw, inside your mouth.','They cut, tear and grind food into small pieces so it is easier to swallow and digest.','Tooth enamel is the hardest substance in the human body.'),
('skeletal','temporal-bones','The temporal bones are on the sides of the skull.','Around and behind each ear.','They protect the sides of the brain and contain the hearing and balance organs.','The hardest part of the temporal bone protects the tiny ear bones and the cochlea.'),
('skeletal','thigh-bone','The thigh bone, or femur, is the longest and strongest bone in your body.','In your upper leg, between your hip and your knee.','It carries your body weight and lets you walk, run and jump.','Your femur is about one quarter of your total height.'),
('skeletal','thoracic-vertebrae','The thoracic vertebrae are the twelve bones of the middle back.','In your upper and middle back, behind your chest.','Each one connects to a pair of ribs and protects the spinal cord.','They move less than neck bones because the ribs hold them steady.'),
('skeletal','tibia','The tibia, or shin bone, is the larger of the two lower leg bones.','On the inner side of the lower leg, just under the skin at the front.','It carries almost all the body''s weight from the knee to the ankle.','The bump on the inside of your ankle is the bottom end of your tibia.'),
('skeletal','toe-bones','Toe bones are phalanges, like finger bones; the big toe has two and the others have three.','In your toes.','They help you balance and push off when you walk and run.','Your big toe carries about twice as much weight as all your other toes when you push off.'),
('skeletal','ulna','The ulna is the longer of the two forearm bones.','On the little-finger side of the forearm.','It forms the main hinge of the elbow with the humerus.','The pointy bump of your elbow is the top of your ulna.'),
('skeletal','upper-arm-bone','The upper arm bone, called the humerus, is the long bone in your upper arm.','Between your shoulder and your elbow.','It lets you lift and move your arm, and muscles like the biceps pull on it.','The ''funny bone'' tingle is actually a nerve passing near the end of the humerus.'),
('skeletal','zygomatic-bones','The zygomatic bones are the cheekbones.','Below and to the side of each eye.','They shape the cheeks and protect the eyes from the side.','The chewing muscle called the masseter attaches to the cheekbone.'),
('muscular','abdominal-muscles','The abdominal muscles, or ''abs'', are flat muscles in the tummy.','On the front and sides of your tummy.','They hold your tummy in, help you sit up and twist, and protect the organs inside.','The ''six-pack'' look comes from bands of tendon crossing one long muscle.'),
('muscular','abs','The rectus abdominis is a long flat muscle.','Down the front of the tummy, from the ribs to the hip bones.','It bends your body forward, like in a sit-up, and supports the organs.','Bands of tendon across it make the ''six-pack'' look.'),
('muscular','achilles-tendon','The Achilles tendon is a thick, strong cord.','At the back of your ankle, joining the calf muscles to the heel bone.','It lets the calf muscles pull up your heel so you can walk, run and jump.','It''s named after the Greek hero Achilles, whose only weak spot was his heel.'),
('muscular','adductors','The adductors are a group of muscles.','On the inside of your thigh.','They pull your legs together and help steady the hips.','Footballers use their adductors a lot for side-foot passes.'),
('muscular','back-muscles','The erector spinae are long muscles.','Running up both sides of the spine.','They keep your back straight and help you stand up tall and lean back.','These muscles work all day to keep you upright, even when you''re just standing.'),
('muscular','biceps','The biceps is a muscle with two heads at the front of the upper arm.','On the front of your upper arm.','It bends your elbow and turns your palm to face up.','''Biceps'' means ''two heads'' — it starts from two places on the shoulder blade.'),
('muscular','brachialis','The brachialis and coracobrachialis are upper-arm muscles.','Underneath the biceps.','The brachialis is the main muscle that bends the elbow; the coracobrachialis pulls the arm forward.','The brachialis does more of the work of bending the elbow than the biceps does.'),
('muscular','calf-muscles','The calf muscles are the gastrocnemius and soleus.','On the back of your lower leg.','They lift your heel so you can stand on tiptoe, walk, run and jump.','They connect to the heel through the Achilles tendon, the strongest tendon in the body.'),
('muscular','chest-muscle','The chest muscle, or pectoralis major, is a big fan-shaped muscle.','Across the front of your chest.','It pulls your arm forward and across your body, like when you push or hug.','Push-ups are one of the best exercises for the pectoralis major.'),
('muscular','deltoid','The deltoid is the rounded triangle-shaped muscle of the shoulder.','Covering the top and sides of the shoulder.','It lifts your arm out to the side, forward and backward.','It''s named after the Greek letter delta (Δ) because of its triangle shape.'),
('muscular','diaphragm','The diaphragm is a dome-shaped sheet of muscle.','Under your lungs, separating the chest from the tummy.','It pulls down when you breathe in, making room for air to rush into the lungs.','Hiccups happen when your diaphragm suddenly twitches.'),
('muscular','face-muscles','The face muscles are small muscles just under the skin.','All over your face: around the eyes, mouth, nose and forehead.','They make facial expressions like smiling, frowning and raising your eyebrows.','Face muscles attach to skin instead of bone, which is why they can make so many expressions.'),
('muscular','foot-muscles','The foot has many small muscles.','In the sole and on top of the foot.','They support the arches, move the toes and help you balance.','Walking barefoot on sand makes these small muscles work harder.'),
('muscular','forearm-extensors','The forearm extensors are a group of muscles.','On the back of your forearm.','They straighten your wrist and fingers and help turn your hand.','''Tennis elbow'' is soreness where these muscles attach near the elbow.'),
('muscular','forearm-flexors','The forearm flexors are a group of muscles.','On the palm side of your forearm.','They bend your wrist and fingers so you can grip and make a fist.','Clench your fist and watch your forearm move — the muscles moving your fingers live there.'),
('muscular','gluteus-maximus','The gluteus maximus is the biggest muscle in your body.','In your bottom.','It straightens your hip so you can stand up, climb stairs and run.','It''s large because humans walk upright on two legs.'),
('muscular','gluteus-medius','The gluteus medius and minimus are smaller bottom muscles.','On the side of the hip, under the gluteus maximus.','They keep your hips level when you stand on one leg or walk.','Without them, your hips would drop with every step you take.'),
('muscular','hamstrings','The hamstrings are three muscles.','On the back of your thigh.','They bend your knee and pull your leg backward.','Sprinters often pull their hamstrings because these muscles work so hard when running fast.'),
('muscular','hand-muscles','The hand has many small muscles.','In the palm, around the thumb and between the finger bones.','They control fine movements like writing, pinching and spreading your fingers.','The fleshy pad at the base of your thumb is made of three small muscles.'),
('muscular','hip-flexors','The hip flexors are the psoas major and iliacus.','Deep inside the lower tummy and the front of the hip.','They lift your thigh up, like when you march or climb stairs.','The psoas is the only muscle that connects the spine to the legs.'),
('muscular','intercostals','The intercostal muscles are thin muscles.','Between the ribs.','They lift and lower the ribcage to help you breathe.','''Intercostal'' means ''between the ribs''.'),
('muscular','jaw-muscles','The chewing muscles are the masseter and the temporalis.','On the sides of your face and head, over the jaw and temples.','They close your jaw strongly so you can bite and chew.','For its size, the masseter is one of the strongest muscles in the body.'),
('muscular','latissimus-dorsi','The latissimus dorsi is the widest muscle of the back.','On the sides of your middle and lower back.','It pulls your arm down and back, like when you climb or swim.','Its name means ''widest of the back'' in Latin.'),
('muscular','neck-muscle','The sternocleidomastoid is a long strap muscle.','On each side of your neck, from behind the ear to the collarbone.','It turns and tilts your head and helps you nod.','Its long name lists where it attaches: sternum, clavicle and the mastoid bone behind the ear.'),
('muscular','obliques','The obliques are layers of muscle: external oblique, internal oblique and transversus abdominis.','On the sides of your tummy.','They twist and bend your body sideways and squeeze the tummy when you cough or laugh.','Their fibres run in different directions, like plywood, which makes the tummy wall strong.'),
('muscular','other-head-muscles','This group includes the eye muscles, tongue muscles and throat muscles.','Inside the head: around the eyeballs, in the tongue and around the throat.','They move your eyes, shape your tongue for talking and squeeze food down when you swallow.','Your eye muscles are some of the fastest muscles in your body.'),
('muscular','other-leg-muscles','These are the deeper muscles of the hip and leg, such as the small hip rotators and deep calf muscles.','Deep in the hip, thigh and lower leg.','They rotate the hip, bend the toes and keep the legs stable when you move.','Six small deep muscles in your hip turn your leg outward.'),
('muscular','other-neck-muscles','These are the deeper muscles of the neck, such as the scalenes and the strap muscles.','In the front and sides of the neck, under the bigger neck muscles.','They hold your head steady, help you swallow and can lift the ribs when you breathe hard.','When you breathe very hard, the scalenes help pull your top ribs up.'),
('muscular','other-trunk-muscles','These include the deep back muscles and the pelvic floor muscles.','Deep along the spine and at the bottom of the pelvis.','They make tiny adjustments to keep your spine steady and hold up the organs in the pelvis.','Some deep back muscles stretch across just one or two vertebrae.'),
('muscular','quadriceps','The quadriceps is a group of four muscles.','On the front of your thigh.','They straighten your knee for kicking, jumping and standing up.','The quadriceps is one of the strongest muscle groups in the body.'),
('muscular','rotator-cuff','The rotator cuff is a group of four muscles (plus the teres major nearby).','Around the shoulder blade and shoulder joint.','They hold the ball of the arm bone in the shoulder socket and rotate the arm.','Baseball pitchers and swimmers often injure their rotator cuff.'),
('muscular','sartorius','The sartorius is the longest muscle in the body.','Running diagonally across the front of the thigh, from hip to knee.','It helps bend and turn the hip and knee, like when you sit cross-legged.','Its name comes from the Latin for tailor, because tailors used to sit cross-legged.'),
('muscular','serratus-anterior','The serratus anterior has jagged, saw-like edges.','On the side of the chest, over the ribs.','It pulls the shoulder blade forward, like when you punch or push.','It''s nicknamed the ''boxer''s muscle''.'),
('muscular','shin-muscle','The tibialis anterior is the main shin muscle.','On the front of your lower leg, beside the shin bone.','It lifts your toes up so your foot doesn''t drag when you walk.','Tap your foot and you can feel this muscle working.'),
('muscular','shin-muscles','The shin and outer leg muscles include the tibialis anterior and the fibularis muscles.','On the front and outer side of the lower leg.','They lift your toes and turn your foot outward.','''Shin splints'' is soreness in these muscles, often from running on hard ground.'),
('muscular','trapezius','The trapezius is a large diamond-shaped muscle.','On your upper back and the back of your neck.','It lifts your shoulders (like shrugging) and pulls your shoulder blades together.','Left and right together, the trapezius looks like a trapezium shape — that''s its name.'),
('muscular','triceps','The triceps is a three-headed muscle at the back of the upper arm.','On the back of your upper arm.','It straightens your elbow, working opposite the biceps.','The triceps is actually bigger than the biceps.'),
('nervous','auditory-tube','The auditory (Eustachian) tube is a narrow tube.','From the middle ear down to the back of the nose.','It keeps the air pressure equal on both sides of the eardrum.','Yawning or swallowing on a plane opens this tube — that''s the ''pop'' you feel.'),
('nervous','basal-ganglia','The basal ganglia are groups of nerve cells: the caudate nucleus, putamen and globus pallidus.','Deep inside each half of the brain.','They help start and control movements and form habits.','Parkinson''s disease affects the basal ganglia, which is why it changes movement.'),
('nervous','brain','The brain is the control centre of your whole body. It is soft, wrinkly and pinkish-grey.','Inside your head, protected by the skull.','It thinks, remembers, feels, and sends messages that control your movements and organs.','Your brain uses about one fifth of all the energy your body makes.'),
('nervous','brainstem','The brainstem is the stalk-like part of the brain made of the midbrain, pons and medulla.','At the base of the brain, connecting it to the spinal cord.','It controls automatic jobs like breathing, heartbeat, swallowing and sleep.','You don''t have to remember to breathe because your brainstem does it for you.'),
('nervous','cerebellum','The cerebellum is a smaller, tightly folded part of the brain.','At the back of the brain, under the cerebrum.','It controls balance, posture and smooth, coordinated movement.','The cerebellum is only about a tenth of the brain''s size but holds more than half its nerve cells.'),
('nervous','cerebrum','The cerebrum is the largest part of the brain, split into left and right halves.','Filling the top and front of the skull.','It handles thinking, memory, language, the senses and voluntary movement.','The left half of the cerebrum controls the right side of the body, and the right half controls the left.'),
('nervous','cochlea','The cochlea is a snail-shaped tube filled with fluid.','In the inner ear, inside the temporal bone.','Tiny hair cells inside it turn sound vibrations into nerve signals.','If you unrolled the cochlea it would be about 3 cm long.'),
('nervous','corpus-callosum','The corpus callosum is a thick band of nerve fibres (shown here with the fornix).','Deep in the middle of the brain, between the left and right halves.','It connects the two halves of the cerebrum so they can share information.','It contains about 200 million nerve fibres.'),
('nervous','cranial-nerves','The cranial nerves are 12 pairs of nerves that come straight out of the brain.','In the head and neck; one, the vagus nerve, reaches down to the chest and tummy.','They control smell, sight, hearing, taste, face movements, swallowing and more.','''Vagus'' means ''wandering'' — the vagus nerve wanders all the way to your gut.'),
('nervous','ear-ossicles','The ossicles are three tiny bones: the hammer (malleus), anvil (incus) and stirrup (stapes).','In the middle ear, between the eardrum and the inner ear.','They pass sound vibrations from the eardrum to the inner ear and make them stronger.','The stirrup (stapes) is the smallest bone in the human body — about 3 mm long.'),
('nervous','eardrum','The eardrum is a thin, tight membrane.','At the end of the ear canal, between the outer and middle ear.','It vibrates when sound waves hit it and passes the vibration to the ossicles.','The eardrum is thinner than a sheet of paper.'),
('nervous','ears','The inner ear contains the snail-shaped cochlea and the balance organ; the eardrum separates it from the outside.','Deep inside the skull, on each side of the head.','They turn sound vibrations into nerve messages and help you keep your balance.','The cochlea is only about the size of a pea.'),
('nervous','eyeball','The eyeball''s tough white outer layer is the sclera; at the front is the clear cornea.','In the eye socket.','The sclera protects the eye and keeps its shape; the cornea bends light into the eye.','The cornea has no blood vessels — it gets oxygen straight from the air.'),
('nervous','eyes','The eyes are ball-shaped organs that let you see.','In the eye sockets at the front of the skull.','They catch light and send pictures to the brain through the optic nerves.','Your eyes see the world upside down; your brain flips the picture the right way up.'),
('nervous','hippocampus','The hippocampus is a curved structure; the amygdala sits just in front of it.','Deep inside the temporal lobe on each side of the brain.','The hippocampus helps form new memories; the amygdala handles feelings like fear.','Hippocampus is Greek for ''seahorse'', because of its shape.'),
('nervous','hypothalamus','The hypothalamus is a tiny area of the brain about the size of an almond.','Below the thalamus, just above the pituitary gland.','It controls body temperature, hunger, thirst and sleep, and tells hormone glands what to do.','It acts like your body''s thermostat, making you sweat or shiver.'),
('nervous','iris','The iris is the coloured ring of the eye.','At the front of the eye, behind the cornea, around the pupil.','It makes the pupil bigger in dim light and smaller in bright light.','Your iris pattern is unique, like a fingerprint.'),
('nervous','lens','The lens is a clear, flexible disc.','Behind the iris and pupil.','It changes shape to focus light sharply onto the retina.','The lens gets stiffer with age, which is why many older people need reading glasses.'),
('nervous','nerves','Nerves are thin cables made of bundles of nerve cells.','Spreading out from the brain and spinal cord to every part of the body.','They carry messages for feeling (like touch and pain) and for moving muscles.','Some nerve messages travel at over 400 km per hour — faster than a racing car.'),
('nervous','optic-nerves','The optic nerves are thick nerves, one from each eye; they cross at the optic chiasm.','From the back of each eye towards the middle of the brain.','They carry signals from the retina to the brain so you can see.','Where the optic nerve leaves the eye there are no light sensors — that''s your blind spot.'),
('nervous','retina','The retina is a thin layer packed with light-sensing cells called rods and cones.','Lining the inside back of the eye.','It turns light into nerve signals that travel to the brain.','There are about 120 million rods and 6 million cones in each retina.'),
('nervous','spinal-cord','The spinal cord is a long bundle of nerves, about as thick as your finger.','Inside the backbone, running down from the brain.','It carries messages between the brain and the rest of the body, and controls quick reflexes.','When you touch something hot, your spinal cord makes you pull away before your brain even notices.'),
('nervous','sympathetic-trunk','The sympathetic trunks are two chains of nerve knots called ganglia.','Along both sides of the spine, from the neck to the tailbone.','They prepare the body for action — the ''fight or flight'' response — speeding up the heart and breathing.','They''re why your heart pounds when you get a fright.'),
('nervous','tear-glands','The tear glands and tear ducts make and drain tears.','Above the outer corner of each eye; the ducts drain into the nose.','They keep the eye moist and wash away dust and germs.','Your nose runs when you cry because tears drain into it.'),
('nervous','thalamus','The thalamus is a pair of egg-shaped structures deep in the brain.','In the centre of the brain, on top of the brainstem.','It acts as a relay station, sorting messages from the senses and sending them to the right part of the cerebrum.','Every sense except smell passes through the thalamus.'),
('nervous','vestibule','The vestibule and the semicircular canals form the balance organ.','In the inner ear, next to the cochlea.','They sense head movement and gravity so you can keep your balance.','Spinning makes you dizzy because the fluid in your balance organ keeps moving after you stop.'),
('circulatory','aorta','The aorta is the largest artery in the body.','It rises from the heart, arches over and runs down in front of the spine.','It carries oxygen-rich blood from the left ventricle out to the whole body.','The aorta is about as wide as a garden hose.'),
('circulatory','arteries','Arteries are thick, stretchy tubes; this group includes the aorta and the main arteries.','Throughout the body, starting from the heart.','They carry blood away from the heart to the body.','You can feel an artery working when you check your pulse on your wrist or neck.'),
('circulatory','cardiac-veins','The cardiac veins and the coronary sinus are veins.','On the surface of the heart.','They collect used blood from the heart muscle and return it to the right atrium.','The coronary sinus is the heart''s own drain pipe.'),
('circulatory','carotid-arteries','The carotid arteries are the main arteries of the neck.','On each side of the neck.','They carry blood to the brain, face and head.','You can feel your carotid pulse just beside your windpipe.'),
('circulatory','coronary-arteries','The coronary arteries are small arteries.','On the outside surface of the heart.','They supply the heart muscle itself with oxygen-rich blood.','A blockage in a coronary artery causes a heart attack.'),
('circulatory','heart','The heart is a strong, hollow muscle about the size of your fist.','In the middle of your chest, a little to the left, between the lungs.','It pumps blood around your whole body, carrying oxygen and food to every cell.','Your heart beats about 100,000 times every day.'),
('circulatory','heart-valves','The heart valves are flaps of tissue (with the small papillary muscles that hold them).','Between the heart chambers and where the big arteries leave the heart.','They open and close to keep blood flowing in one direction only.','The ''lub-dub'' sound of your heartbeat is the valves snapping shut.'),
('circulatory','hepatic-portal-vein','The hepatic portal vein is a large vein.','Below the liver, collecting blood from the stomach, intestines and spleen.','It carries nutrient-rich blood from the gut to the liver to be processed.','About three quarters of the liver''s blood supply comes through this vein.'),
('circulatory','jugular-veins','The jugular veins are large veins.','On each side of the neck.','They drain blood from the brain, face and neck back toward the heart.','You can sometimes see the external jugular vein when someone sings loudly or strains.'),
('circulatory','left-atrium','The left atrium is the upper left chamber of the heart.','At the top and back of the left side of the heart.','It receives oxygen-rich blood from the lungs and passes it to the left ventricle.','The four pulmonary veins all empty into the left atrium.'),
('circulatory','left-ventricle','The left ventricle is the lower left chamber and the strongest part of the heart.','At the bottom of the left side of the heart.','It pumps oxygen-rich blood into the aorta and out to the whole body.','Its muscular wall is about three times thicker than the right ventricle''s.'),
('circulatory','pulmonary-arteries','The pulmonary arteries branch from the pulmonary trunk.','From the heart into the left and right lungs.','They carry oxygen-poor blood from the heart to the lungs to pick up oxygen.','They''re the only arteries that carry oxygen-poor blood.'),
('circulatory','pulmonary-veins','The pulmonary veins are four veins.','From the lungs into the left side of the heart.','They carry fresh, oxygen-rich blood from the lungs back to the heart.','They''re the only veins that carry oxygen-rich blood.'),
('circulatory','right-atrium','The right atrium is the upper right chamber of the heart.','At the top of the right side of the heart.','It receives oxygen-poor blood from the body and passes it to the right ventricle.','A small patch of cells in the right atrium starts every heartbeat — the heart''s natural pacemaker.'),
('circulatory','right-ventricle','The right ventricle is the lower right chamber of the heart.','At the bottom of the right side of the heart, towards the front.','It pumps oxygen-poor blood through the pulmonary arteries to the lungs.','Its wall is thinner than the left ventricle''s because the lungs are close by.'),
('circulatory','veins','Veins are thinner tubes that hold blood flowing back to the heart; this group includes the vena cava.','Throughout the body, many just under the skin.','They carry blood back to the heart from the body.','Many veins have one-way valves that stop blood flowing backward.'),
('circulatory','vena-cava','The venae cavae are the two biggest veins: the superior and inferior vena cava.','Running into the right side of the heart from above and below.','They bring used, oxygen-poor blood from the body back into the heart.','The inferior vena cava is the largest vein in the body.'),
('respiratory','bronchi','The bronchi are the branching tubes of the airway.','Splitting from the bottom of the windpipe into each lung.','They carry air deep into the lungs through smaller and smaller branches.','The airways branch so much they''re called the ''bronchial tree''.'),
('respiratory','diaphragm','The diaphragm is a dome-shaped sheet of muscle.','Under the lungs, separating the chest from the tummy.','It pulls down when you breathe in, making space so air rushes into the lungs.','Hiccups happen when your diaphragm suddenly twitches.'),
('respiratory','larynx','The larynx, or voice box, is made of cartilage, including the Adam''s apple.','At the top of the windpipe, in the front of the neck.','It holds the vocal cords that vibrate to make your voice, and protects the airway when you swallow.','Boys'' voices get deeper as teenagers because the larynx grows bigger.'),
('respiratory','left-lower-lobe','The lower lobe of the left lung.','At the bottom and back of the left lung, resting on the diaphragm.','It exchanges oxygen and carbon dioxide.','The left lung has just two lobes, making room for the heart.'),
('respiratory','left-lung','The left lung is a little smaller and has two lobes.','On the left side of the chest.','It swaps gases: oxygen goes into the blood and carbon dioxide comes out.','It has a notch called the cardiac notch where the heart fits.'),
('respiratory','left-upper-lobe','The upper lobe of the left lung.','At the top and front of the left lung.','It exchanges oxygen and carbon dioxide.','It has a tongue-like part called the lingula, which curves around the heart.'),
('respiratory','lobar-bronchi','The lobar bronchi are the second branches of the airway.','Inside the lungs, one going to each lobe.','They carry air to each lobe of the lungs.','There are five lobar bronchi — one for each lobe.'),
('respiratory','lungs','The lungs are two soft, spongy organs.','In your chest, inside the ribcage, on each side of the heart.','They take in oxygen from the air you breathe and get rid of carbon dioxide.','If you spread out all the tiny air sacs in your lungs, they would cover a tennis court.'),
('respiratory','main-bronchi','The main bronchi are the first two branches of the windpipe.','From the bottom of the trachea into the left and right lungs.','They carry air into each lung.','The right main bronchus is wider and steeper, so swallowed objects usually go that way.'),
('respiratory','right-lower-lobe','The lower lobe of the right lung.','At the bottom and back of the right lung, resting on the diaphragm.','It exchanges oxygen and carbon dioxide.','Lower lobes get the most air and blood when you''re standing up.'),
('respiratory','right-lung','The right lung is the larger lung and has three lobes.','On the right side of the chest.','It swaps gases: oxygen goes into the blood and carbon dioxide comes out.','The right lung is bigger because the heart takes up room on the left.'),
('respiratory','right-middle-lobe','The middle lobe of the right lung — only the right lung has one.','In the front middle of the right lung.','It exchanges oxygen and carbon dioxide.','It''s the smallest of the five lobes.'),
('respiratory','right-upper-lobe','The upper lobe of the right lung.','At the top of the right lung, reaching up to the collarbone.','It exchanges oxygen and carbon dioxide like the other lobes.','Each lobe has its own airway branch, so surgeons can remove one lobe and leave the rest working.'),
('respiratory','segmental-bronchi','The segmental bronchi are smaller airway branches.','Inside each lobe, branching to lung segments.','They carry air to each segment, leading on to tiny bronchioles and air sacs.','Your airways branch about 23 times before reaching the air sacs.'),
('respiratory','trachea','The trachea, or windpipe, is a tube held open by rings of cartilage.','In the front of your neck, running down into your chest.','It carries air from your throat down towards the lungs.','The rings are C-shaped so your food pipe behind can bulge when you swallow.'),
('digestive','appendix','The appendix is a small, finger-shaped pouch.','Attached to the start of the large intestine, in the lower right of the tummy.','It may store helpful gut bacteria; you can live healthily without it.','If the appendix gets inflamed (appendicitis), doctors usually remove it.'),
('digestive','ascending-colon','The ascending colon is the first part of the large intestine.','Running up the right side of the tummy.','It absorbs water and salts from the leftover food.','It starts at a pouch called the caecum, where the appendix is attached.'),
('digestive','bile-duct','The bile duct is a thin tube.','From the liver and gall bladder to the duodenum.','It carries bile into the small intestine.','It joins with the pancreatic duct just before entering the duodenum.'),
('digestive','descending-colon','The descending colon is part of the large intestine.','Running down the left side of the tummy.','It stores waste and absorbs more water from it.','Waste here is already quite solid.'),
('digestive','duodenum','The duodenum is the first, C-shaped part of the small intestine.','Just after the stomach, curving around the pancreas.','Bile and pancreatic juices mix with food here to break it down further.','Duodenum means ''twelve'' — it''s about twelve finger-widths long.'),
('digestive','gallbladder','The gall bladder is a small, pear-shaped pouch (shown with the bile duct).','Tucked under the liver on the right side.','It stores bile from the liver and squeezes it into the small intestine to help digest fat.','People can live without a gall bladder; bile just drips straight from the liver instead.'),
('digestive','gums','The gums (gingiva) are pink tissue.','Around the base of the teeth in both jaws.','They hold the teeth firmly and protect the roots.','Brushing and flossing keep gums healthy and stop them bleeding.'),
('digestive','jejunum-ileum','The jejunum and ileum are the long, coiled middle and last parts of the small intestine.','Filling the middle of the tummy.','Most nutrients are absorbed here through millions of tiny finger-like villi.','The villi give the small intestine a surface area about the size of a small flat.'),
('digestive','large-intestine','The large intestine is a wide tube that forms a frame around the small intestine.','Around the edge of the tummy: up the right side, across the top and down the left.','It soaks up water from leftover food and turns it into poo.','Trillions of helpful bacteria live in your large intestine.'),
('digestive','liver','The liver is the largest organ inside your body and is dark red-brown.','In the upper right part of the tummy, under the ribs.','It makes bile to help digest fat, stores energy and cleans harmful things out of the blood.','The liver can grow back even if part of it is removed.'),
('digestive','mouth','The mouth includes the tongue, gums and soft palate.','At the front of the face, where food enters.','Teeth chew food, saliva wets it and the tongue rolls it into a ball to swallow.','You make about one litre of saliva every day.'),
('digestive','oesophagus','The oesophagus, or food pipe, is a muscular tube about 25 cm long.','From the back of the throat down through the chest to the stomach.','Its muscles squeeze in waves to push swallowed food down to the stomach.','Food reaches your stomach even if you''re upside down, because the oesophagus squeezes it along.'),
('digestive','palate','The soft palate is the soft back part of the roof of the mouth; the uvula hangs from it.','At the back of the roof of the mouth.','It lifts up when you swallow to stop food going into your nose.','The uvula is the little dangly thing you see at the back of your throat.'),
('digestive','pancreas','The pancreas is a long, soft gland shaped a bit like a fish.','Behind the stomach, in the upper tummy.','It makes digestive juices for the small intestine and the hormone insulin to control blood sugar.','The pancreas makes about 1.5 litres of digestive juice every day.'),
('digestive','pharynx','The pharynx, or throat, is a muscular tube.','Behind the nose and mouth, above the oesophagus and windpipe.','It carries food to the oesophagus and air to the windpipe.','A flap called the epiglottis covers the windpipe when you swallow, so food goes the right way.'),
('digestive','salivary-glands','The salivary glands are three pairs of glands: parotid, submandibular and sublingual.','In front of the ears, under the jaw and under the tongue.','They make saliva, which wets food and starts digesting starch.','Just smelling tasty food can make these glands start working.'),
('digestive','sigmoid-colon','The sigmoid colon is the S-shaped last part of the colon.','In the lower left of the tummy, leading to the rectum.','It holds waste until it''s time to go to the toilet.','''Sigmoid'' means shaped like the Greek letter sigma (S).'),
('digestive','small-intestine','The small intestine is a long, narrow, coiled tube.','In the middle of the tummy, surrounded by the large intestine.','It finishes digesting food and soaks up the nutrients into the blood.','Stretched out, your small intestine would be about 6 metres long.'),
('digestive','stomach','The stomach is a stretchy, J-shaped bag made of muscle.','In the upper left part of the tummy, under the ribs.','It churns food and mixes it with strong acid and juices to break it down.','Your stomach makes a new lining every few days so its own acid doesn''t digest it.'),
('digestive','tongue','The tongue is a strong, flexible muscle covered in taste buds.','On the floor of the mouth.','It tastes food, moves it around for chewing, pushes it back to swallow and helps you speak.','You have between 2,000 and 8,000 taste buds.'),
('digestive','transverse-colon','The transverse colon is the middle part of the large intestine.','Running across the upper tummy, below the stomach.','It keeps absorbing water and moves waste along.','It''s the longest and most movable part of the colon.'),
('urinary','bladder','The bladder is a stretchy, balloon-like bag made of muscle.','Low in the tummy, behind the hip bones.','It stores urine until you go to the toilet.','An adult bladder can hold about 400–600 ml of urine.'),
('urinary','kidneys','The kidneys are two bean-shaped organs, each about the size of your fist.','In your back, just below the ribs, one on each side of the spine.','They filter waste and extra water out of the blood to make urine.','Your kidneys filter all of your blood about 40 times a day.'),
('urinary','renal-arteries','The renal arteries branch from the abdominal aorta.','From the aorta into each kidney.','They bring blood into the kidneys to be filtered.','About a fifth of all the blood pumped by the heart goes to the kidneys.'),
('urinary','renal-pelvis','The renal pelvis is a funnel-shaped space.','Inside each kidney, where it meets the ureter.','It collects urine from the kidney and funnels it into the ureter.','Kidney stones sometimes form in the renal pelvis.'),
('urinary','renal-veins','The renal veins are large veins.','From each kidney to the inferior vena cava.','They carry cleaned blood out of the kidneys back toward the heart.','The left renal vein is longer because it has to cross over the aorta.'),
('urinary','ureters','The ureters are two thin, muscular tubes.','Running down from each kidney to the bladder.','They carry urine from the kidneys to the bladder.','The ureters squeeze urine along in small waves every few seconds.'),
('urinary','urethra','The urethra is a tube.','From the bottom of the bladder to the outside of the body.','It carries urine out of the body.','Rings of muscle around it keep it closed until you decide to go.'),
('reproductive','epididymis','The epididymis is a tightly coiled tube.','On the back of each testis.','It stores sperm while they mature.','Uncoiled, each epididymis would be about 6 metres long.'),
('reproductive','penis','The penis is the external male organ.','At the front of the pelvis.','It carries urine and, in adults, sperm out of the body through the urethra.','The urethra inside is shared by the urinary and reproductive systems.'),
('reproductive','prostate','The prostate is a gland about the size of a walnut.','Below the bladder, around the urethra.','It adds fluid that protects sperm.','The prostate tends to grow larger as men get older.'),
('reproductive','seminal-glands','The seminal glands are two small glands.','Behind the bladder.','They make most of the fluid that carries and feeds sperm.','This fluid contains sugar that gives sperm energy.'),
('reproductive','sperm-ducts','The sperm ducts (ductus deferens) are muscular tubes.','From each epididymis up into the pelvis, joining near the prostate.','They carry sperm towards the urethra.','Each duct loops up and over the ureter on its way.'),
('reproductive','testes','The testes are two oval glands.','Below the penis, in a pouch of skin called the scrotum.','They make sperm cells and the hormone testosterone.','They sit outside the body because sperm develop best slightly cooler than body temperature.');
insert into public.badges (code, name, description, icon) values
('first-organ','First Discovery','Learned your first organ','🔬'),
('curious-mind','Curious Mind','Learned 25 organs','🧠'),
('system-master','System Master','Learned every organ in a body system','🏆'),
('sharpshooter','Sharpshooter','Reached wave 3 in Organ Blaster with 90% accuracy','🎯'),
('master-builder','Master Builder','Got 3 stars in System Builder','🧩'),
('all-systems-go','All Systems Go','3 stars in all four System Builder systems','⚡'),
('top-of-class','Top of the Class','Scored 90% or more in a test','⭐'),
('perfect-score','Perfect Score','Scored 100% in a test of 5+ questions','💯'),
('on-fire','On Fire','Learned 7 days in a row','🔥'),
('xp-1000','XP Champion','Earned 1000 XP','🚀')
