-- BodyQuest 3D seed data (generated). Run AFTER migrations/001_schema.sql.
-- Safe to re-run: it refreshes the built-in content and question bank (student results are kept).
begin;

delete from public.organ_models;

delete from public.organ_content;

on conflict (code) do update set name = excluded.name, description = excluded.description, icon = excluded.icon;

-- built-in questions keep the same ids every time, so re-running this updates them without touching student results
on conflict (id) do update set system = excluded.system, level = excluded.level, type = excluded.type, prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, slug = excluded.slug;

on conflict (question_id) do update set answer = excluded.answer;

commit;
